package jp.tapmarker;
import java.util.*;
public class StableTransitionTest {
 static int n;static void check(boolean b,String label){if(!b)throw new AssertionError(label);n++;System.out.println("PASS "+label);}
 static PhaseEngine.Watch match(String id){PhaseEngine.Watch w=new PhaseEngine.Watch();w.id=id;w.regionId="R";w.condition=PhaseEngine.MATCH;w.reference=new float[]{1};return w;}
 public static void main(String[] args){PhaseEngine e=new PhaseEngine();e.strictRuntime=true;PhaseEngine.Region r=new PhaseEngine.Region();r.id="R";e.regions.put(r.id,r);PhaseEngine.Phase p=new PhaseEngine.Phase();p.id="S";p.name="S";e.phases.put(p.id,p);PhaseEngine.Watch a=match("A"),b=match("B");p.watches.add(a);e.enter("S",0);Map<String,float[]> samples=new HashMap<>();samples.put("R",new float[]{1});e.observe(samples,1);check(e.poll()==null,"one matching frame never triggers");e.observe(samples,2);check(e.poll()==a,"two matching frames confirm");a.nextPhase="S";e.finish(a,3);e.observe(samples,4);e.observe(samples,5);check(e.poll()==a,"main self-loop repeats after fresh two-frame confirmation");samples.put("R",new float[]{0});e.observe(samples,6);samples.put("R",new float[]{1});e.observe(samples,7);check(e.poll()==null,"reappeared display needs two frames");e.observe(samples,8);check(e.poll()==a,"display departure and reappearance rearms");e.enter("S",9);b.action=PhaseEngine.BACK;p.watches.add(b);e.observe(samples,10);e.observe(samples,11);check(e.poll()==null&&e.diagnostic.startsWith("複数"),"ambiguous equal-priority branches wait");b.priority=20;e.observe(samples,12);check(e.poll()==null,"priority never selects a runtime branch");e.enter("S",13);e.observe(samples,14);e.observe(samples,15);samples.put("R",new float[]{0});e.observe(samples,16);check(e.poll()==null,"stale image candidate discarded before execution");p.watches.clear();a.condition=PhaseEngine.CHANGE;a.nextPhase="";p.watches.add(a);e.enter("S",20);e.observe(samples,21);samples.put("R",new float[]{1});e.observe(samples,22);check(e.poll()==null,"change needs second stable observation");e.observe(samples,23);check(e.poll()==a,"stable changed image confirms change action");a.condition=PhaseEngine.MATCH;a.reference=null;e.enter("S",30);check(e.validateStart().isEmpty(),"unrecorded image does not block automaton start");e.observe(samples,31);e.observe(samples,32);check(e.poll()==null&&e.diagnostic.contains("未記録"),"unrecorded image never fires and reports reason");a.regionId="missing";check(!e.validateStart().isEmpty(),"structural reference errors still block start");System.out.println("TOTAL "+n+" stable transition checks passed; device UI not tested.");}
}
